#!/usr/bin/env node
//
// Permission catalog delta migration generator.
//
// Compares the current docs/permissions-action-manifest.json against the
// catalog rows in the live postgres (via DATABASE_URL) and emits a new
// migration file that UPSERTs additions and DELETEs removals. The output
// filename follows the project convention: 0NNN_permissions_seed_actions
// _delta_NNN.sql, where NNN is the next available number.
//
// Run after editing docs/permissions-action-manifest.json (typically
// generated by scripts/generate-permission-manifest.mjs after adding a
// new MCP tool or REST route). The migration runner picks up the delta
// on next boot; CI's check-permission-catalog.mjs only checks the
// manifest + TS codegen are in sync, so a missing delta is operator
// responsibility.
//
// Why not regenerate 0145? Because 0145 is the snapshot at Wave A and is
// frozen post-deploy per CLAUDE.md's immutability rule. Editing applied
// migration bodies trips the migrate runner's checksum guard and
// stalls every redeploy until MIGRATE_ALLOW_HEADER_RESTAMP is set
// (the 2026-04-18 incident).

import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { resolve, join } from 'node:path';
import { execSync } from 'node:child_process';

const ROOT = resolve(new URL('.', import.meta.url).pathname.replace(/^\/([A-Za-z]):\//, '$1:/'), '..');
const MANIFEST_PATH = join(ROOT, 'docs/permissions-action-manifest.json');
const MIGRATIONS_DIR = join(ROOT, 'infra/postgres/migrations');

function nextDeltaNumber() {
  // Find max 0NNN_permissions_seed_actions_delta_*.sql + 1; or 0151 if
  // none exist yet (Wave A snapshot is 0145).
  const files = readdirSync(MIGRATIONS_DIR).filter((f) =>
    /^\d{4}_permissions_seed_actions_delta_/.test(f),
  );
  if (files.length === 0) return '0151';
  const max = files.reduce((m, f) => Math.max(m, parseInt(f.slice(0, 4), 10)), 0);
  return String(max + 1).padStart(4, '0');
}

async function fetchAppliedCatalog() {
  // Read straight from postgres via psql in-container. Falls back to
  // parsing the most-recent delta + the snapshot if DATABASE_URL is
  // unreachable (rare).
  try {
    const sql = "SELECT id FROM permissions ORDER BY id;";
    const out = execSync(
      `docker compose exec -T postgres psql -U bigbluebam -d bigbluebam -t -A -c "${sql}"`,
      { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf8' },
    );
    return new Set(out.split('\n').map((l) => l.trim()).filter(Boolean));
  } catch (err) {
    console.error('✗ failed to query live postgres for catalog state:', err.message);
    console.error('  start the dev stack (docker compose up -d postgres) and retry.');
    process.exit(1);
  }
}

async function main() {
  if (!existsSync(MANIFEST_PATH)) {
    console.error(`✗ manifest not found at ${MANIFEST_PATH}.`);
    process.exit(1);
  }
  const manifest = JSON.parse(readFileSync(MANIFEST_PATH, 'utf8'));
  const manifestIds = new Set(manifest.permissions.map((p) => p.id));
  const appliedIds = await fetchAppliedCatalog();

  const added = manifest.permissions.filter((p) => !appliedIds.has(p.id));
  const removed = [...appliedIds].filter((id) => !manifestIds.has(id)).sort();

  if (added.length === 0 && removed.length === 0) {
    console.log('✓ catalog is in sync with applied DB; no delta needed.');
    return;
  }

  const num = nextDeltaNumber();
  const filename = `${num}_permissions_seed_actions_delta_${num}.sql`;
  const path = join(MIGRATIONS_DIR, filename);

  const lines = [];
  lines.push(`-- ${filename}`);
  lines.push('-- Why: Catalog delta. Adds permissions that landed since the previous');
  lines.push('--   seed (snapshot 0145 + any prior deltas) and removes any rows that');
  lines.push('--   were retired. Generated by scripts/build-permission-delta.mjs.');
  lines.push('-- Client impact: additive (new rows) + minor cleanup (removals).');
  lines.push('--   Re-running is safe; INSERT...ON CONFLICT and DELETE both idempotent.');
  lines.push('');

  if (added.length > 0) {
    lines.push(`-- ${added.length} new permission(s)`);
    lines.push('INSERT INTO permissions (id, app, resource, verb, description, is_destructive, requires_confirmation, is_read) VALUES');
    const rows = added.map((p) => {
      const desc = `${p.app} ${p.resource} ${p.verb}`;
      const sqlBool = (b) => (b ? 'true' : 'false');
      const sqlString = (s) => "'" + String(s).replace(/'/g, "''") + "'";
      return `    (${sqlString(p.id)}, ${sqlString(p.app)}, ${sqlString(p.resource)}, ${sqlString(p.verb)}, ${sqlString(desc)}, ${sqlBool(p.is_destructive)}, ${sqlBool(p.requires_confirmation)}, ${sqlBool(p.is_read)})`;
    });
    lines.push(rows.join(',\n'));
    lines.push('ON CONFLICT (id) DO UPDATE SET');
    lines.push('    app = EXCLUDED.app,');
    lines.push('    resource = EXCLUDED.resource,');
    lines.push('    verb = EXCLUDED.verb,');
    lines.push('    description = EXCLUDED.description,');
    lines.push('    is_destructive = EXCLUDED.is_destructive,');
    lines.push('    requires_confirmation = EXCLUDED.requires_confirmation,');
    lines.push('    is_read = EXCLUDED.is_read;');
    lines.push('');
  }

  if (removed.length > 0) {
    lines.push(`-- ${removed.length} retired permission(s)`);
    lines.push(`DELETE FROM permissions WHERE id IN (`);
    const escaped = removed.map((id) => "    '" + id.replace(/'/g, "''") + "'");
    lines.push(escaped.join(',\n'));
    lines.push(');');
    lines.push('');
  }

  writeFileSync(path, lines.join('\n'));
  console.log(`✓ wrote ${path}`);
  console.log(`  added: ${added.length}, removed: ${removed.length}`);
  console.log(`  apply with: docker compose run --rm migrate`);
}

main();
